// HTTP Response Headers from Origin API (Product Catalog Endpoint)
HTTP/1.1 200 OK
Content-Type: application/json

// Browser caches for 60s; CDN (s-maxage) caches for 1 hour;
// Serve stale for 60s while fetching fresh in background; serve stale for 24h if origin returns 5xx!
Cache-Control: public, max-age=60, s-maxage=3600, stale-while-revalidate=60, stale-if-error=86400

// CDN-only tag for O(1) targeted purge when product_992 or category_shoes updates
Surrogate-Key: product_992 category_shoes storefront_us

// Prevent cache key fragmentation: normalize only on required headers
Vary: Accept-Encoding
